  it("shows '3 ideas' badge when idea_count > 0", () => {
    render(<GapCard gap={baseGap} />);
    expect(screen.getByText(/3 ideas/)).toBeInTheDocument();
  });

  it("does not show badge when idea_count is 0", () => {
