/**
 * Traces API Client — BATCH-21/TASK-01
 *
 * Typed functions for trace observability endpoints.
 * Endpoint shapes from backend/api/routes/traces.py:
 *   GET /traces/summary     → {total_traces, active_traces, error_rate}
 *   GET /traces/trace/{id}  → {trace_id, spans: [{name, duration_ms, ...}]}
 *   GET /traces/metrics     → {p50_ms, p99_ms, error_rate}
 */

import { apiFetch } from "./client";

// ── Types ────────────────────────────────────────────────────────

export interface TraceSummary {
  total_traces: number;
  active_traces: number;
  error_rate: number;
}

export interface TraceSpan {
  name: string;
  duration_ms: number;
  [key: string]: unknown;
}

export interface TraceDetail {
  trace_id: string;
  spans: TraceSpan[];
}

export interface TraceMetrics {
  p50_ms: number;
  p99_ms: number;
  error_rate: number;
}

// ── API Functions ────────────────────────────────────────────────

export function getTraceSummary(): Promise<TraceSummary> {
  return apiFetch<TraceSummary>("/traces/summary");
}

export function getTrace(traceId: string): Promise<TraceDetail> {
  return apiFetch<TraceDetail>(`/traces/trace/${traceId}`);
}

export function getTraceMetrics(): Promise<TraceMetrics> {
  return apiFetch<TraceMetrics>("/traces/metrics");
}

/**
 * TraceSummary — BATCH-21/TASK-01
 *
 * Displays total traces, active traces, and error rate in a summary card.
 */

import type { TraceSummary as TraceSummaryData } from "@/api/traces";

interface TraceSummaryProps {
  summary: TraceSummaryData;
}

function formatPercent(value: number): string {
  return `${(value * 100).toFixed(1)}%`;
}

export function TraceSummary({ summary }: TraceSummaryProps) {
  return (
    <div className="rounded-lg border bg-card p-6 space-y-4" data-testid="trace-summary">
      <h3 className="text-sm font-medium text-muted-foreground">Trace Overview</h3>
      <div className="grid gap-4 sm:grid-cols-3">
        <div>
          <p className="text-3xl font-bold" data-testid="total-traces">
            {summary.total_traces.toLocaleString()}
          </p>
          <p className="text-sm text-muted-foreground">Total Traces</p>
        </div>
        <div>
          <p className="text-3xl font-bold" data-testid="active-traces">
            {summary.active_traces.toLocaleString()}
          </p>
          <p className="text-sm text-muted-foreground">Active Traces</p>
        </div>
        <div>
          <p className="text-3xl font-bold" data-testid="error-rate">
            {formatPercent(summary.error_rate)}
          </p>
          <p className="text-sm text-muted-foreground">Error Rate</p>
        </div>
      </div>
    </div>
  );
}

/**
 * SpanDetail — BATCH-21/TASK-01
 *
 * Displays the list of spans for a specific trace.
 */

import type { TraceSpan } from "@/api/traces";

interface SpanDetailProps {
  spans: TraceSpan[];
  traceId: string;
}

function formatDuration(ms: number): string {
  if (ms >= 1000) {
    return `${(ms / 1000).toFixed(2)}s`;
  }
  return `${ms.toFixed(0)}ms`;
}

export function SpanDetail({ spans, traceId }: SpanDetailProps) {
  return (
    <div className="rounded-lg border bg-card p-6 space-y-4" data-testid="span-detail">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-medium text-muted-foreground">
          Trace Spans
        </h3>
        <span className="text-xs font-mono text-muted-foreground" data-testid="span-trace-id">
          {traceId}
        </span>
      </div>
      <div className="space-y-2">
        {spans.map((span, idx) => (
          <div
            key={`${span.name}-${idx}`}
            className="flex items-center justify-between rounded-md border px-4 py-2"
            data-testid={`span-row-${idx}`}
          >
            <span className="text-sm font-medium" data-testid={`span-name-${idx}`}>
              {span.name}
            </span>
            <span className="text-sm text-muted-foreground" data-testid={`span-duration-${idx}`}>
              {formatDuration(span.duration_ms)}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
