import { TraceSummary } from "@/components/traces/trace-summary";
import { SpanDetail } from "@/components/traces/span-detail";
import type { TraceSummary as TraceSummaryData, TraceSpan } from "@/api/traces";

// ── Shared fixtures ────────────────────────────────────────

